"""Small helpers for reading the service's settings."""

import json
import os
from pathlib import Path

DEFAULT_PATH = Path("~/.config/service/settings.json").expanduser()
DEFAULT_TIMEOUT = 30
DEFAULT_RETRIES = 3


class SettingsError(Exception):
    """Raised when the settings file cannot be read."""


def load(path=DEFAULT_PATH):
    """Read the settings file, or return the defaults when it is missing."""
    if not path.exists():
        return {"timeout": DEFAULT_TIMEOUT, "retries": DEFAULT_RETRIES}
    try:
        with path.open() as handle:
            data = json.load(handle)
    except json.JSONDecodeError as error:
        raise SettingsError(f"{path}: {error}") from error
    data.setdefault("timeout", DEFAULT_TIMEOUT)
    data.setdefault("retries", DEFAULT_RETRIES)
    return data


def timeout(settings):
    """The request timeout in seconds."""
    return int(settings.get("timeout", DEFAULT_TIMEOUT))


def retries(settings):
    """How many times to retry a failed request."""
    return int(settings.get("retries", DEFAULT_RETRIES))


def from_environment():
    """Settings overridden by SERVICE_TIMEOUT and SERVICE_RETRIES."""
    settings = load()
    if "SERVICE_TIMEOUT" in os.environ:
        settings["timeout"] = int(os.environ["SERVICE_TIMEOUT"])
    if "SERVICE_RETRIES" in os.environ:
        settings["retries"] = int(os.environ["SERVICE_RETRIES"])
    return settings

