package queue

import (
	"errors"
	"sync"
	"time"
)

// ErrFull is returned when the queue is at capacity.
var ErrFull = errors.New("queue: full")

// Queue is a bounded first-in, first-out queue safe for concurrent use.
type Queue struct {
	mu       sync.Mutex
	items    []string
	capacity int
	created  time.Time
}

// New returns an empty queue holding at most capacity items.
func New(capacity int) *Queue {
	return &Queue{capacity: capacity, created: time.Now()}
}

// Push adds an item, or returns ErrFull.
func (q *Queue) Push(item string) error {
	q.mu.Lock()
	defer q.mu.Unlock()
	if len(q.items) >= q.capacity {
		return ErrFull
	}
	q.items = append(q.items, item)
	return nil
}

// Pop removes and returns the oldest item.
func (q *Queue) Pop() (string, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	if len(q.items) == 0 {
		return "", false
	}
	item := q.items[0]
	q.items = q.items[1:]
	return item, true
}

// Len reports how many items are queued.
func (q *Queue) Len() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.items)
}

