use std::collections::HashMap;
use std::fmt;

/// A word count, most frequent first.
#[derive(Debug, Default)]
pub struct Counts {
    words: HashMap<String, usize>,
    total: usize,
}

impl Counts {
    /// Counts the words of `text`, ignoring case and punctuation.
    pub fn from_text(text: &str) -> Self {
        let mut counts = Self::default();
        for word in text.split_whitespace() {
            let cleaned: String = word
                .chars()
                .filter(|c| c.is_alphanumeric())
                .collect::<String>()
                .to_lowercase();
            if cleaned.is_empty() {
                continue;
            }
            *counts.words.entry(cleaned).or_insert(0) += 1;
            counts.total += 1;
        }
        counts
    }

    /// How many words were counted.
    pub fn total(&self) -> usize {
        self.total
    }

    /// How many distinct words there are.
    pub fn distinct(&self) -> usize {
        self.words.len()
    }

    /// The `n` most frequent words, ties broken alphabetically.
    pub fn top(&self, n: usize) -> Vec<(&str, usize)> {
        let mut pairs: Vec<(&str, usize)> =
            self.words.iter().map(|(w, c)| (w.as_str(), *c)).collect();
        pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)));
        pairs.truncate(n);
        pairs
    }
}

impl fmt::Display for Counts {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for (word, count) in self.top(10) {
            writeln!(f, "{count:>6} {word}")?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
